#!/usr/bin/env python3
"""Regenerate crates/stonesoup-scenarios/src/lot1_fixtures.rs from verification/fixtures/lot1_kalman.json."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
JSON_PATH = ROOT / "verification" / "fixtures" / "lot1_kalman.json"
OUT = ROOT / "crates" / "stonesoup-scenarios" / "src" / "lot1_fixtures.rs"


def main() -> None:
    data = json.loads(JSON_PATH.read_text(encoding="utf-8"))
    n = len(data["measurements"])
    lines = [
        "// @generated by tools/python/fixtures_to_rust.py — do not edit",
        f"pub const NUM_STEPS: usize = {n};",
    ]
    for name, key, cols in [
        ("MEASUREMENTS", "measurements", 2),
        ("TRUTH", "truth", 4),
        ("TRACK_REF", "track", 4),
    ]:
        lines.append(f"pub const {name}: [[f64; {cols}]; NUM_STEPS] = [")
        for row in data[key]:
            lines.append(f"    {row},")
        lines.append("];")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("wrote", OUT)


if __name__ == "__main__":
    main()
